style.css:
@-moz-document domain("roblox.com") {
/* Main background */
  body,
  .rbx-body,
  #react-app,
  .container-main,
  .content {
    background-color: #0f0f12 !important;
    color: #e8e8e8 !important;
  }

  /* Header / Top bar */
  .rbx-header,
  .navbar,
  header {
    background-color: #16161a !important;
    border-bottom: 1px solid #2a2a30 !important;
  }

  /* Left navigation */
  .rbx-left-col,
  .left-col {
    background-color: #16161a !important;
  }

  /* Cards / boxes */
  .game-card,
  .item-card,
  .avatar-card,
  .section-content,
  .profile-header,
  .card {
    background-color: #1c1c22 !important;
    border-radius: 12px !important;
    border: 1px solid #2a2a30 !important;
  }

  /* Buttons */
  .btn-primary-md,
  .btn-growth-md,
  .btn-common-play-game-lg {
    background: linear-gradient(135deg, #00a2ff, #0066cc) !important;
    border: none !important;
    border-radius: 8px !important;
    color: white !important;
  }

  .btn-primary-md:hover,
  .btn-growth-md:hover {
    background: linear-gradient(135deg, #33b5ff, #0088ee) !important;
  }

  /* Text */
  h1, h2, h3, h4, h5, h6,
  .text-name,
  .font-header-2 {
    color: #f0f0f0 !important;
  }

  a {
    color: #4da6ff !important;
  }

  a:hover {
    color: #80c4ff !important;
  }

  /* Input fields */
  input, textarea, select {
    background-color: #1c1c22 !important;
    border: 1px solid #333 !important;
    color: #e8e8e8 !important;
    border-radius: 8px !important;
  }

  /* Scrollbar (Chrome / Edge) */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-track {
    background: #0f0f12;
  }
  ::-webkit-scrollbar-thumb {
    background: #333;
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #555;
  }
}
